css:
.ss-locrail__track{display:flex;gap:20px;overflow-x:auto;scroll-behavior:smooth;scroll-snap-type:x mandatory;padding-bottom:4px}
.ss-locrail__track::-webkit-scrollbar{height:6px}
.ss-locrail__track::-webkit-scrollbar-thumb{background:var(--line)}
.ss-loc{flex:0 0 320px;scroll-snap-align:start;border:1px solid var(--line);background:var(--card);padding:28px}
.ss-loc[hidden]{display:none}
.ss-loc__dots{display:flex;gap:6px;min-height:9px;margin-bottom:14px}
.ss-loc__dots span{width:8px;height:8px;border-radius:50%;display:inline-block}
.ss-loc__head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;margin-bottom:4px}
.ss-loc__c{font-family:var(--font-heading);font-weight:700;font-size:19px;line-height:1.6;margin:0}
.ss-loc__n{font-weight:700;font-size:13px;color:var(--muted);margin-right:8px}
.ss-loc__s{font:700 11px/1 var(--font-body);color:var(--muted)}
.ss-loc__name{font-size:13px;font-weight:600;line-height:1.6;color:var(--muted);margin:0 0 10px}
.ss-loc__phone{font-size:14px;line-height:1.6;color:var(--muted);margin:0 0 16px}
.ss-loc__phone a{color:inherit;text-decoration:none}
.ss-loc__phone a:hover{color:var(--accent)}
.ss-loc__dir{margin:0 0 16px}
.ss-loc__dir a{display:inline-block;padding:4px 0;font:700 13px/1.6 var(--font-body);color:var(--accent);text-decoration:none}
.ss-loc__dir a:hover{text-decoration:underline}
.ss-loc__tags{display:flex;flex-wrap:wrap;gap:6px}
.ss-loc__tags span{border:1px solid var(--line);padding:5px 8px;font:700 10px/1 var(--font-body);letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
@media (max-width:640px){.ss-loc{flex-basis:82vw}}
